#!/bin/bash
# One-liner de despliegue de Claude Code para Juan
# Password: vanejuanpabloana01

set -e

echo "🔐 Validación de acceso requerida..."
read -s -p "Introduce la contraseña: " pass
echo ""

if [ "$pass" != "vanejuanpabloana01" ]; then
    echo "❌ Contraseña incorrecta. Acceso denegado."
    exit 1
fi

echo "✅ Acceso concedido. Iniciando despliegue de Claude Code..."

# 1. Instalación de dependencias básicas (Node.js)
if ! command -v node &> /dev/null; then
    echo "📦 Instalando Node.js..."
    curl -fsSL https://deb.nodesource.com/setup_22.x | sudo -E bash -
    sudo apt-get install -y nodejs
fi

# 2. Instalación de Claude Code
echo "🚀 Instalando @anthropic-ai/claude-code..."
sudo npm install -g @anthropic-ai/claude-code

# 3. Restauración de la configuración privada
echo "⚙️ Restaurando configuración personalizada..."
mkdir -p ~/.claude
echo "" | base64 -d | tar -xz -C ~/.claude

echo "🎉 ¡Despliegue completado! Ya puedes ejecutar 'claude' con tu configuración habitual."
